import json

config = {
  "$schema": "https://raw.githubusercontent.com/googleapis/release-please/main/schemas/config.json",
  "separate-pull-requests": False,
  "pull-request-title-pattern": "chore: release v${version}",
  "changelog-sections": [
    {"type": "feat", "section": "Features"},
    {"type": "fix", "section": "Bug Fixes"},
    {"type": "build", "section": "Build System"},
    {"type": "perf", "section": "Performance Improvements"},
    {"type": "revert", "section": "Reverts"},
    {"type": "docs", "section": "Documentation", "hidden": True},
    {"type": "style", "section": "Styles", "hidden": True},
    {"type": "chore", "section": "Miscellaneous", "hidden": True},
    {"type": "refactor", "section": "Code Refactoring", "hidden": True},
    {"type": "test", "section": "Tests", "hidden": True},
    {"type": "ci", "section": "Continuous Integration", "hidden": True}
  ],
  "packages": {
    ".": {
      "release-type": "node",
      "component": "cipher-box",
      "include-component-in-tag": False,
      "release-as": "2.0.0",
      "extra-files": [
        {"type": "json", "path": "apps/desktop/src-tauri/tauri.conf.json", "jsonpath": "$.version"}
      ]
    }
  }
}
json.dump(config, open('release-please-config.json','w'), indent=2)
open('release-please-config.json','a').write('\n')

json.dump({".": "1.0.0"}, open('.release-please-manifest.json','w'), indent=2)
open('.release-please-manifest.json','a').write('\n')

pkg = json.load(open('package.json'))
new_pkg = {}
for k, v in pkg.items():
    new_pkg[k] = v
    if k == 'packageManager':
        new_pkg['engines'] = {'node': '22'}
if 'engines' not in new_pkg:
    new_pkg['engines'] = {'node': '22'}
json.dump(new_pkg, open('package.json','w'), indent=2)
open('package.json','a').write('\n')
print("config, manifest, package.json engines written")
EOF
